Approach: three small, separately testable components (limiter, spend guard, TTL cache) with injected time, assembled in a factory that fixes the order of checks. Distinct error codes let clients treat rate limits (retry soon) differently from budget exhaustion (stop retrying). In a multi-process deployment the limiter and spend state would live in Redis with atomic operations; the interfaces here stay the same.

**`tenant_gate.py`**

```python
from __future__ import annotations

import hashlib
import json
import math
from collections.abc import Awaitable, Callable
from dataclasses import dataclass
from typing import Annotated

from fastapi import Depends, FastAPI, Header
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

PROMPT_VERSION = "v1"
MODEL = "small-model"


@dataclass(frozen=True, slots=True)
class Generation:
    text: str
    cost_usd: float


Generate = Callable[[str], Awaitable[Generation]]


class TenantLimiter:
    """Token bucket per tenant. take() returns 0.0 if allowed, else seconds to wait."""

    def __init__(self, rate: float, burst: float, clock: Callable[[], float]) -> None:
        self.rate, self.burst, self._clock = rate, burst, clock
        self._state: dict[str, tuple[float, float]] = {}

    def take(self, tenant: str, cost: float = 1.0) -> float:
        now = self._clock()
        tokens, last = self._state.get(tenant, (self.burst, now))
        tokens = min(self.burst, tokens + (now - last) * self.rate)
        if tokens >= cost:
            self._state[tenant] = (tokens - cost, now)
            return 0.0
        self._state[tenant] = (tokens, now)
        return (cost - tokens) / self.rate


class SpendGuard:
    """Daily budget per tenant; the day boundary comes from the injected clock."""

    def __init__(self, daily_budget_usd: float, clock: Callable[[], float]) -> None:
        self.budget, self._clock = daily_budget_usd, clock
        self._spent: dict[tuple[str, int], float] = {}

    def _key(self, tenant: str) -> tuple[str, int]:
        return tenant, int(self._clock() // 86400)

    def allows(self, tenant: str, estimate_usd: float) -> bool:
        return self._spent.get(self._key(tenant), 0.0) + estimate_usd <= self.budget

    def record(self, tenant: str, actual_usd: float) -> None:
        key = self._key(tenant)
        self._spent[key] = self._spent.get(key, 0.0) + actual_usd

    def spent(self, tenant: str) -> float:
        return self._spent.get(self._key(tenant), 0.0)


class TTLCache:
    def __init__(self, ttl_s: float, clock: Callable[[], float]) -> None:
        self._ttl, self._clock = ttl_s, clock
        self._data: dict[str, tuple[float, str]] = {}

    def get(self, key: str) -> str | None:
        item = self._data.get(key)
        if item is None or item[0] <= self._clock():
            self._data.pop(key, None)
            return None
        return item[1]

    def put(self, key: str, value: str) -> None:
        self._data[key] = (self._clock() + self._ttl, value)


def cache_key(tenant: str, prompt: str, temperature: float) -> str:
    blob = json.dumps({"t": tenant, "pv": PROMPT_VERSION, "m": MODEL, "p": prompt, "temp": temperature},
                      sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(blob.encode()).hexdigest()


class ChatIn(BaseModel):
    prompt: str = Field(min_length=1)
    temperature: float = Field(0.0, ge=0.0, le=2.0)


def tenant_id(x_tenant_id: Annotated[str, Header()]) -> str:
    return x_tenant_id      # module level: with postponed annotations FastAPI resolves names via module globals


def create_app(*, clock: Callable[[], float], generate: Generate, rate: float = 1.0, burst: float = 2,
               daily_budget_usd: float = 0.01, estimate_usd: float = 0.004,
               cache_ttl_s: float = 60.0) -> FastAPI:
    limiter = TenantLimiter(rate, burst, clock)
    spend = SpendGuard(daily_budget_usd, clock)
    cache = TTLCache(cache_ttl_s, clock)
    app = FastAPI()

    @app.post("/chat")
    async def chat(body: ChatIn, tenant: Annotated[str, Depends(tenant_id)]) -> JSONResponse:
        wait = limiter.take(tenant)
        if wait > 0:
            return JSONResponse({"error": "rate_limited"}, status_code=429,
                                headers={"Retry-After": str(math.ceil(wait))})
        key = cache_key(tenant, body.prompt, body.temperature)
        if body.temperature == 0.0 and (hit := cache.get(key)) is not None:
            return JSONResponse({"answer": hit, "cached": True, "cost_usd": 0.0})
        if not spend.allows(tenant, estimate_usd):
            return JSONResponse({"error": "budget_exhausted"}, status_code=429)
        try:
            gen = await generate(body.prompt)
        except Exception:
            return JSONResponse({"error": "upstream_failed"}, status_code=502)
        spend.record(tenant, gen.cost_usd)
        if body.temperature == 0.0:
            cache.put(key, gen.text)
        return JSONResponse({"answer": gen.text, "cached": False, "cost_usd": gen.cost_usd})

    return app
```

**`test_tenant_gate.py`**

```python
import pytest
from fastapi.testclient import TestClient

from tenant_gate import Generation, create_app


class Harness:
    def __init__(self, **kw):
        self.now = [0.0]
        self.calls = 0
        self.fail = False

        async def generate(prompt: str) -> Generation:
            self.calls += 1
            if self.fail:
                raise RuntimeError("provider down")
            return Generation(f"answer to {prompt}", 0.004)

        self.app = create_app(clock=lambda: self.now[0], generate=generate, **kw)
        self.client = TestClient(self.app)

    def chat(self, prompt="hi", tenant="acme", **extra):
        headers = {"X-Tenant-Id": tenant} if tenant else {}
        return self.client.post("/chat", json={"prompt": prompt, **extra}, headers=headers)


@pytest.fixture
def h():
    return Harness(rate=1.0, burst=2, daily_budget_usd=0.01, cache_ttl_s=60)


def test_burst_then_429_with_retry_after(h):
    codes = [h.chat(f"p{i}").status_code for i in range(3)]
    assert codes == [200, 200, 429]
    r = h.chat("p9")
    assert r.status_code == 429 and r.json() == {"error": "rate_limited"}
    assert r.headers["retry-after"] == "1"


def test_bucket_refills_with_the_injected_clock():
    h = Harness(rate=1.0, burst=2, daily_budget_usd=1.0)
    h.chat("a"), h.chat("b")
    assert h.chat("c").status_code == 429
    h.now[0] += 1.0
    assert h.chat("c").status_code == 200


def test_limits_are_per_tenant(h):
    h.chat("a"), h.chat("b")
    assert h.chat("c").status_code == 429
    assert h.chat("c", tenant="other").status_code == 200


def test_cache_hit_is_free_and_skips_the_provider():
    h = Harness(rate=100, burst=100, daily_budget_usd=0.01)
    first = h.chat("same").json()
    second = h.chat("same").json()
    assert first["cached"] is False and second["cached"] is True
    assert second["cost_usd"] == 0.0 and h.calls == 1


def test_cache_is_isolated_by_tenant_and_ignores_hot_temperatures():
    h = Harness(rate=100, burst=100, daily_budget_usd=1.0)
    h.chat("same")
    assert h.chat("same", tenant="other").json()["cached"] is False
    h.chat("warm", temperature=0.7)
    assert h.chat("warm", temperature=0.7).json()["cached"] is False
    assert h.calls == 4


def test_cache_entries_expire():
    h = Harness(rate=100, burst=100, daily_budget_usd=1.0, cache_ttl_s=60)
    h.chat("same")
    h.now[0] = 59.0
    assert h.chat("same").json()["cached"] is True
    h.now[0] = 61.0
    assert h.chat("same").json()["cached"] is False


def test_budget_exhaustion_is_a_distinct_error_and_resets_next_day():
    h = Harness(rate=100, burst=100, daily_budget_usd=0.01)
    assert h.chat("a").status_code == 200
    assert h.chat("b").status_code == 200
    r = h.chat("c")
    assert r.status_code == 429 and r.json() == {"error": "budget_exhausted"}
    assert "retry-after" not in r.headers and h.calls == 2
    h.now[0] = 86400.0
    assert h.chat("c").status_code == 200


def test_budget_is_per_tenant():
    h = Harness(rate=100, burst=100, daily_budget_usd=0.004)
    assert h.chat("a").status_code == 200
    assert h.chat("b").json() == {"error": "budget_exhausted"}
    assert h.chat("b", tenant="other").status_code == 200


def test_provider_failure_is_502_and_costs_nothing():
    h = Harness(rate=100, burst=100, daily_budget_usd=0.004)
    h.fail = True
    r = h.chat("a")
    assert r.status_code == 502 and r.json() == {"error": "upstream_failed"}
    h.fail = False
    assert h.chat("a").status_code == 200


def test_validation_and_missing_tenant_header(h):
    assert h.chat("hi", tenant=None).status_code == 422
    assert h.client.post("/chat", json={"prompt": ""}, headers={"X-Tenant-Id": "a"}).status_code == 422
```

Run: `pytest -q` (all 10 tests pass against this solution).

